// Package bpf embeds the compiled eBPF objects from the bpf/ directory.
//
// Each bpf/*.bpf.c file becomes one object. The *_bpfel.go and *_bpfel.o
// files next to this one are generated by bpf2go and committed, so building
// the agent only needs Go. After changing anything under bpf/, run
// `make generate` (needs clang and llvm-strip) and commit the result.
package bpf

//go:generate go tool bpf2go -tags linux -target amd64 -no-global-types -type ht_event cuda ../../bpf/cuda.bpf.c -- -I../../bpf/headers -I../../bpf/lib -Wall
//go:generate go tool bpf2go -tags linux -target amd64 -no-global-types sched ../../bpf/sched.bpf.c -- -I../../bpf/headers -I../../bpf/lib -Wall
//go:generate go tool bpf2go -tags linux -target amd64 -no-global-types proc ../../bpf/proc.bpf.c -- -I../../bpf/headers -I../../bpf/lib -Wall
//go:generate go tool bpf2go -tags linux -target amd64 -no-global-types net ../../bpf/net.bpf.c -- -I../../bpf/headers -I../../bpf/lib -Wall
//go:generate go tool bpf2go -tags linux -target amd64 -no-global-types ioctl ../../bpf/ioctl.bpf.c -- -I../../bpf/headers -I../../bpf/lib -Wall
